def jos(n, k):
    if k == 1:
        return n - 1
    stack = []
    while n >= k:
        stack.append(n)
        n -= n // k
    r = 0
    for m in range(2, n + 1):
        r = (r + k) % m
    while stack:
        m = stack.pop()
        r -= m % k
        if r < 0:
            r += m
        else:
            r += r // (k - 1)
    return r
