from math import isqrt
def pos(n):
    if n == 1:
        return 0, 0
    k = (isqrt(n - 1) + 1) // 2
    t = n - (2 * k - 1) ** 2
    if t <= 2 * k:
        return k, t - k
    if t <= 4 * k:
        return k - (t - 2 * k), k
    if t <= 6 * k:
        return -k, k - (t - 4 * k)
    return -k + (t - 6 * k), -k
def num(x, y):
    k = max(abs(x), abs(y))
    if k == 0:
        return 1
    base = (2 * k - 1) ** 2
    if x == k and y > -k:
        t = y + k
    elif y == k:
        t = 2 * k + (k - x)
    elif x == -k:
        t = 4 * k + (k - y)
    else:
        t = 6 * k + (x + k)
    return base + t
